using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    private static string NewAudioId(){using var crypto=new Crypto();return Convert.ToHexString(crypto.GenerateRandomBytes(16)).ToLowerInvariant();}
    private static Resource NewPreset()=>new KiwiAudioPreset();
    private static string[] PackedStrings(Variant value){if(value.VariantType==Variant.Type.PackedStringArray)return value.AsStringArray();var result=new System.Collections.Generic.List<string>();if(value.VariantType==Variant.Type.Array)foreach(var item in value.AsGodotArray())result.Add(item.AsString());return result.ToArray();}
    private static string ScalarPrefix(string text,int maximum){var result=new System.Text.StringBuilder();int count=0;foreach(var rune in text.EnumerateRunes()){if(count++>=maximum)break;result.Append(rune.ToString());}return result.ToString();}
    public void save_preset(Control o,string kind)
    {
        string error=Document(o).Call("midi_timing_error").AsString();if(error.Length>0){notice(o,error);return;}var generator=Dict(o,"_preview_payload").Duplicate(true);var document=Document(o).Call("snapshot").As<Resource>();var actor=Session(o).Call("primary_actor").AsGodotObject();var effects=Get(effect_owner(o),"effects",new GArray()).AsGodotArray().Duplicate(true);var instrument=actor!=null?Get(actor.Get("values").AsGodotDictionary(),"instrument",new Settings()).AsGodotDictionary().Duplicate(true):new Settings();using var presets=new AudioPresetOperations();var pattern=actor!=null?presets.pattern_data(actor,Document(o)):new Settings();if(kind=="generator"&&!preview_matches_controls(o)){Field<Label>(o,"status").Text="Wait for the current generator preview before saving its preset.";return;}name_dialog(o,"Save "+kind+" preset",Get(Dict(o,"_library_entry"),"label",Document(o).Get("title")).AsString(),Callable.From<string>(name=>{var preset=NewPreset();preset.Set("id",NewAudioId());preset.Set("label",name);preset.Set("kind",kind);switch(kind){case "generator":preset.Set("data",new Settings{["id"]=generator["id"],["settings"]=generator["settings"].AsGodotDictionary().Duplicate(true),["seed"]=generator["seed"]});break;case "effects":preset.Set("data",new Settings{["effects"]=effects});break;case "instrument":preset.Set("data",instrument);break;case "pattern":if(pattern.Count==0){notice(o,"Select a note pattern first.");return;}preset.Set("data",pattern);preset.Set("tags",PackedStrings(Get(pattern,"tags",new GArray())));break;case "composition":preset.Set("composition",document);break;}persist_preset(o,preset);}),false);
    }
    public Resource? prepare_native_preset_export(Resource? preset)=>preset?.Duplicate(true);
    public void complete_native_preset_export(Control o,Resource preset,Settings target){if(target.Count==0)return;string destination=Get(target,"path","").AsString();if(destination.Length==0)return;if(Godot.FileAccess.FileExists(destination)){notice(o,"Choose a new filename; existing presets are never overwritten by Export.");return;}preset.ResourcePath="";var error=ResourceSaver.Save(preset,destination);if(error!=Error.Ok)notice(o,"Could not export native preset: "+error);else Field<Label>(o,"status").Text="Exported native preset. External sample/IR references stay linked; use Collect Portable for compositions.";}
    public void import_native_preset(Control o)
    {
        var picker=new FileDialog{Title="Import trusted Kiwi audio preset",Access=FileDialog.AccessEnum.Filesystem,FileMode=FileDialog.FileModeEnum.OpenFile,Filters=new[]{"*.tres ; Trusted native audio presets"}};o.AddChild(picker);picker.FileSelected+=location=>{picker.QueueFree();using(var file=Godot.FileAccess.Open(location,Godot.FileAccess.ModeFlags.Read)){if(file==null||file.GetLength()>128UL*1024*1024){notice(o,"Choose a readable native preset up to 128 MiB.");return;}}var preset=ResourceLoader.Load(location,"",ResourceLoader.CacheMode.Ignore);using var library=new AudioLibraryOperations();if(!IsScript(preset,"res://Workspaces/AudioWorkspace/KiwiAudioPreset.cs")||!library.valid_entry(new Settings{["kind"]="preset",["preset"]=preset})){notice(o,"This is not a supported Kiwi audio preset.");return;}preset=preset.Duplicate(true);preset.Set("id",NewAudioId());preset.ResourcePath="";persist_preset(o,preset);};picker.Canceled+=picker.QueueFree;picker.PopupCenteredRatio(.7f);
    }
    public void preset_recovery_dialog(Control o)
    {
        using var store=new AudioPresetStoreOperations();var entries=store.recoverable();var dialog=window(o,"Recover removed presets and earlier versions",new Vector2I(720,470));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var list=new ItemList{SizeFlagsVertical=Control.SizeFlags.ExpandFill};host.AddChild(list);foreach(var entry in entries)list.AddItem(entry["label"].AsString());label(host,"Restore creates an independent library copy. The recovery original and any current preset are preserved.");ActionButton(host,"Restore selected as new preset",()=>{var selected=list.GetSelectedItems();if(selected.Length==0)return;using var recovery=new AudioPresetStoreOperations();string error=recovery.restore(entries[selected[0]]);if(error.Length>0)notice(o,error);else{Field<Control>(o,"library").Call("reload");windowNode.QueueFree();Field<Label>(o,"status").Text="Restored preset as an independent copy.";}});
    }
    public void save_layer_bundle(Control o)
    {
        using var bundles=new AudioLayerBundleOperations();var result=bundles.selected((RefCounted)Document(o),Items(Session(o),"selected_ids"));if(Get(result,"error","").AsString().Length>0){notice(o,result["error"].AsString());return;}var document=result["document"].As<Resource>();name_dialog(o,"Save selected layer bundle","Layer bundle",Callable.From<string>(name=>{var preset=NewPreset();preset.Set("id",NewAudioId());preset.Set("kind","bundle");preset.Set("label",name);preset.Set("composition",document);persist_preset(o,preset);}),false);
    }
    public void audition_native_preset(Control o,Resource preset)
    {
        RefCounted document=new KiwiAudioDocument();var options=new Settings{["sample_rate"]=44100,["bit_depth"]=16,["start"]=0.0,["duration"]=8.0,["include_tail"]=false};string kind=preset.Get("kind").AsString();switch(kind)
        {
            case "composition":case "bundle":var composition=preset.Get("composition").AsGodotObject();if(composition==null)return;document=composition.Call("snapshot").As<RefCounted>();options["duration"]=Math.Min(15,document.Call("duration").AsDouble());break;
            case "pattern":case "instrument":var preview=new KiwiAudioEditSession();preview.Set("document",document);var pattern=preset;if(kind=="instrument"){pattern=NewPreset();pattern.Set("kind","pattern");pattern.Set("label",preset.Get("label"));var notes=new GArray();for(int i=0;i<3;i++)notes.Add(new Settings{["pitch"]=new[]{60,64,67}[i],["start"]=(double)i,["duration"]=1.0,["velocity"]=(double).7});pattern.Set("data",new Settings{["notes"]=notes,["instrument"]=preset.Get("data").AsGodotDictionary().Duplicate(true),["pattern_beats"]=4.0});}using(var presets=new AudioPresetOperations()){string problem=presets.apply_pattern(preview,pattern,0,"",true);if(problem.Length>0){notice(o,problem);return;}}document=preview.Get("document").As<RefCounted>();options["duration"]=Math.Min(15,document.Call("duration").AsDouble());break;
            case "effects":var clip=Session(o).Call("primary_clip").AsGodotObject();if(clip==null){notice(o,"Select a clip to audition this effect chain without applying it.");return;}document=Document(o).Call("snapshot").As<RefCounted>();document.Call("actor_for_clip",clip.Get("id")).AsGodotObject().Get("values").AsGodotDictionary()[new StringName("effects")]=Get(preset.Get("data").AsGodotDictionary(),"effects",new GArray()).AsGodotArray().Duplicate(true);options["clip_ids"]=new GArray{clip.Get("id")};options["start"]=clip.Get("start_time");options["duration"]=Math.Min(8,clip.Get("duration").AsDouble());break;
            default:return;
        }
        string destination=temporary_audio("preview_preset");ulong token=Session(o).GetInstanceId();Work(o,"preset_audition",0,job=>{using var renderer=new AudioRendererOperations();var result=renderer.render(document,destination,options,job);result["owner"]=token;return result;});
    }
    public void persist_preset(Control o,Resource preset){if(preset.Get("kind").AsString()=="pattern"){using var presets=new AudioPresetOperations();string problem=presets.validate_pattern(preset.Get("data").AsGodotDictionary());if(problem.Length>0){notice(o,problem);return;}}string directory=ProjectSettings.GlobalizePath("user://audio_workspace/presets");DirAccess.MakeDirRecursiveAbsolute(directory);var error=ResourceSaver.Save(preset,directory.PathJoin(preset.Get("id").AsString()+".tres"));if(error!=Error.Ok)notice(o,"Could not save preset.");else{Field<Control>(o,"library").Call("reload");Field<Label>(o,"status").Text="Saved editable preset: "+preset.Get("label").AsString();}}
    public Settings prepare_instrument_sample(Control o){var actor=Session(o).Call("primary_actor").AsGodotObject();if(actor==null)return new Settings();var context=picker_context(o);context["actor"]=actor;return context;}
    public void complete_instrument_sample(Control o,Settings context,string chosen,bool empty)
    {
        if(!PickerCurrent(o,context)){notice(o,"The composition changed while choosing a file. Repeat this action in the intended document.");return;}if(chosen.Length==0||empty)return;var actor=context["actor"].AsGodotObject();SessionAction(o,"Assign sample",()=>{var values=actor.Get("values").AsGodotDictionary();using var instruments=new AudioInstrumentOperations();var patch=Get(values,"instrument",instruments.default_instrument("sampler")).AsGodotDictionary();if(Get(patch,"kind","").AsString()=="multisample"){var maps=Get(patch,"multisamples",new GArray()).AsGodotArray();maps.Add(new Settings{["sample"]=chosen,["root_pitch"]=60,["low"]=0,["high"]=127,["velocity_low"]=0,["velocity_high"]=1});patch["multisamples"]=maps;}else patch["sample"]=chosen;values[new StringName("instrument")]=patch;values[new StringName("notes_dirty")]=true;});render_dirty_notes(o);
    }
    public void complete_generator_sample(Control o,string chosen,bool empty){if(chosen.Length==0||empty)return;Dict(o,"_generator_settings")["sample"]=chosen;generate_preview(o);}
    public void pattern_tags_dialog(Control o)
    {
        var actor=Session(o).Call("primary_actor").AsGodotObject();var clip=Session(o).Call("primary_clip").AsGodotObject();if(actor==null||clip==null||!Session(o).Call("can_edit",clip.Get("id")).AsBool())return;var owner=Session(o);string id=clip.Get("id").AsString();name_dialog(o,"Pattern tags (comma separated)",string.Join(", ",PackedStrings(Get(actor.Get("values").AsGodotDictionary(),"pattern_tags",new GArray()))),Callable.From<string>(text=>{if(Session(o)!=owner)return;var current=Document(o).Call("actor_for_clip",id).AsGodotObject();if(current==null||!owner.Call("can_edit",id).AsBool())return;var tags=new GArray();foreach(string value in text.Split(',',StringSplitOptions.RemoveEmptyEntries)){string tag=ScalarPrefix(value.Trim(),128);if(tag.Length>0&&!tags.Contains(tag)&&tags.Count<32)tags.Add(tag);}SessionAction(o,"Edit pattern tags",()=>current.Get("values").AsGodotDictionary()[new StringName("pattern_tags")]=tags);}),false);
    }
    public void import_pattern_json(Control o)
    {
        var picker=new FileDialog{Title="Import data-only pattern JSON",FileMode=FileDialog.FileModeEnum.OpenFile,Access=FileDialog.AccessEnum.Filesystem,Filters=new[]{"*.json ; Pattern JSON"}};o.AddChild(picker);var owner=Session(o);long revision=owner.Get("revision").AsInt64();picker.FileSelected+=file=>{picker.QueueFree();if(Session(o)!=owner||owner.Get("revision").AsInt64()!=revision){notice(o,"The document changed while choosing a pattern. Import it again.");return;}using var presets=new AudioPresetOperations();var result=presets.import_pattern_json(file);if(Get(result,"error","").AsString().Length>0){notice(o,result["error"].AsString());return;}var preset=result["preset"].AsGodotObject();string error=presets.apply_pattern(owner,preset,Position(o),owner.Get("selected_track").AsString(),false);if(error.Length>0)notice(o,error);else{render_dirty_notes(o);Field<Label>(o,"status").Text="Imported editable pattern: "+preset.Get("label").AsString();}};picker.Canceled+=picker.QueueFree;picker.PopupCenteredRatio(.7f);
    }
    public void export_pattern_json(Control o)
    {
        var actor=Session(o).Call("primary_actor").AsGodotObject();using var edits=new AudioEditSessionOperations();if(actor==null||!edits.is_note_source(actor)){notice(o,"Select a note pattern first.");return;}var preset=NewPreset();preset.Set("kind","pattern");preset.Set("label",actor.Get("display_name"));using var presets=new AudioPresetOperations();var data=presets.pattern_data(actor,Document(o));preset.Set("data",data);preset.Set("tags",PackedStrings(Get(data,"tags",new GArray())));var encoded=presets.to_json_text(preset);if(Get(encoded,"error","").AsString().Length>0){notice(o,encoded["error"].AsString());return;}var picker=new FileDialog{Title="Export data-only pattern JSON",FileMode=FileDialog.FileModeEnum.SaveFile,Access=FileDialog.AccessEnum.Filesystem,Filters=new[]{"*.json ; Pattern JSON"},CurrentFile="pattern.json"};o.AddChild(picker);picker.FileSelected+=file=>{picker.QueueFree();using var output=new AudioPresetOperations();string error=output.export_pattern_json(file,preset);if(error.Length>0)notice(o,error);else Field<Label>(o,"status").Text="Exported editable pattern JSON.";};picker.Canceled+=picker.QueueFree;picker.PopupCenteredRatio(.7f);
    }
}
